#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Pickups;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Pickups;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Definitions;
using PVZEngine.Tools.Random;

namespace MVZ2.GameContent.Buffs.Enemies
{
    [AutoBuffDefinition(VanillaBuffNames.Enemy.gemCarrier)]
    public class GemCarrierBuff : BuffDefinition
    {
        public GemCarrierBuff(string nsp, string name) : base(nsp, name)
        {
            AddTrigger(VanillaLevelCallbacks.ENEMY_DROP_REWARDS, PostEnemyDropRewardsCallback);
        }
        private void PostEnemyDropRewardsCallback(EntityCallbackParams param, CallbackResultVoid result)
        {
            var enemy = param.entity;
            var buffs = enemy.GetBuffs<GemCarrierBuff>();
            foreach (var buff in buffs)
            {
                var gemID = gemsID.WeightedRandom(gemWeights, enemy.DropRNG);
                enemy.Produce(gemID);
                buff.Remove();
            }
        }
        private static readonly List<NamespaceID> gemsID = new List<NamespaceID>()
        {
            VanillaPickupID.emerald,
            VanillaPickupID.ruby,
            VanillaPickupID.diamond,
        };
        private static readonly List<float> gemWeights = new List<float>()
        {
            100,
            20,
            1,
        };
    }
}
